\label{lem:divX}
Let $X$ be a $C^1$ vector field on $\mathbb{R}^{n+1}$ tangent to the leaves. Then, along every leaf $L$,
\begin{equation}\label{eq:divX}
\operatorname{div} X=\operatorname{div}_LX-\langle X,T\rangle .
\end{equation}

\label{lem:lapL}
For $f\in C^\infty(\mathbb R^{n+1})$ and any leaf $L\in \mathfrak{F}$, we have
\begin{equation}\label{eq:lapL}
\Delta_L f = \operatorname{tr}_{TL}\operatorname{Hess} f
+nH\,N(f) \qquad\text{on }L.
\end{equation}
In particular, for $\rho(x):=\sqrt{1+|x|^2}$, one has $\Delta_L\rho\le n(1+|H|).$

\label{lem:divV}
The vector field
\begin{equation}\label{eq:V}
V:=H^pN+\frac{p}{n}H^{p-1}T
\end{equation}
is smooth on $\mathbb R^{n+1}$, and
\begin{equation}\label{eq:divV}
\operatorname{div}V
=
\frac{p}{n}H^{p-1}|A|^2-nH^{p+1}
\ge (p-n)H^{p+1}
=(p-n)|H|^{p+1}
\ge0.
\end{equation}

\label{prop:int}
For every $\chi\in C^\infty_c(\mathbb R^{n+1})$, we have
\begin{equation}\label{eq:int}
\begin{aligned}
(p-n)\int_{\mathbb R^{n+1}}\chi^q H^{p+1}
\le{}&(p+1)\int_{\mathbb R^{n+1}}
|H|^p\,|\nabla(\chi^q)|+p\int_{\mathbb R^{n+1}}
H^{p-1}\,\|\operatorname{Hess}\chi^q\|.
\end{aligned}
\end{equation}

Under the above notation, we have
\begin{equation}\label{eq:cutoff}
|\nabla\chi_R|\le\frac{C_0}{R},
\qquad
\|\operatorname{Hess}\chi_R\|\le\frac{C_0}{R^2}.
\end{equation}
